vim.api.nvim_create_user_command("GenerateStaticLsp", function()
	local excluded_name = {
		gitlab_duo = true,
		rust_analyzer = true,
	}
	local excluded_binaries = {
		npm = true,
		dotnet = true,
		npx = true,
		python = true,
		java = true,
		node = true,
		perl = true,
	}

	local configs = vim.lsp.get_configs()

	---@type table
	local lines = {
		"-- ==========================================================",
		"-- AUTO-GENERATED BY :GenerateStaticLsp. DO NOT EDIT MANUALLY.",
		"-- ==========================================================",
	}
	for _, config in ipairs(configs) do
		if not excluded_name[config.name] then
			local cmd = config.cmd
			local exe = nil
			if type(cmd) == "table" then
				exe = cmd[1]
			elseif type(cmd) == "string" then
				exe = cmd
			end

			if exe and not excluded_binaries[exe] and vim.fn.executable(exe) == 1 then
				table.insert(lines, string.format('vim.lsp.enable(%q)', config.name))
			end
		end
	end



	local target_path = vim.fn.stdpath("config") .. "/lua/config/auto_enabled_lsp.lua"
	local file, err = io.open(target_path, "w")
	if not file then
		vim.notify("Failed to generate LSP config: " .. tostring(err), vim.log.levels.ERROR)
		return
	end

	file:write(table.concat(lines, "\n"))
	file:close()

	vim.notify("Successfully generated static LSP config with " .. (#lines - 3) .. " servers!", vim.log.levels.INFO)
end, {})
